function makeWorld(seed=(Math.random()*4294967296)>>>0){let state=seed>>>0;const rng=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};let planets=[];const count=1+Math.floor(rng()*3);for(let i=0;i<count;i++){let u=.26+(i+rng()*.5)*.46/count,r=25+rng()*25,x=120+760*u,y=430-290*u+(rng()-.5)*85,kind=Math.floor(rng()*3),points=[],n=kind===0?20:kind===1?5:9,stretch=.65+rng()*.7,phase=rng()*6.28;for(let j=0;j<n;j++){let a=phase+j/n*Math.PI*2,rad=r*(kind===2?.65+rng()*.35:1);points.push({x:Math.cos(a)*rad,y:Math.sin(a)*rad*stretch});}let moving=rng()<.6,a=rng()*Math.PI*2,speed=moving?5+rng()*8:0;planets.push({x,y,r,points:hull(points),vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,tint:['#917566','#747c9a','#607e87'][kind]});}for(const p of planets)p.mass=Math.round((p.r/35)**3*(7000+rng()*5000));const storms=[];for(let i=0,n=1+Math.floor(rng()*2);i<n;i++){const a=rng()*Math.PI*2,start=Math.round(2+rng()*8);storms.push({x:350+rng()*380,y:180+rng()*210,r:85+rng()*40,start,end:Math.min(30,start+10+Math.round(rng()*8)),ax:Math.cos(a)*(6+rng()*6),ay:Math.sin(a)*(6+rng()*6)});}return {seed:seed>>>0,planets,storms};}
