function environment(world,x,y,t){let gx=0,gy=0,wx=0,wy=0;const planets=[];for(const p of world.planets){const c=planetAt(p,t),dx=c.x-x,dy=c.y-y,soft=p.r*.8,den=(dx*dx+dy*dy+soft*soft)**1.5,range=gravityRadius(p),distance=Math.hypot(dx,dy),u=range?Math.max(0,Math.min(1,(range-distance)/(range*.2))):0,taper=u*u*(3-2*u),k=(p.mass||0)*taper/den,ax=dx*k,ay=dy*k;gx+=ax;gy+=ay;planets.push({ax,ay,strength:Math.hypot(ax,ay)});}for(const w of world.storms||[]){if(t<w.start||t>=w.end)continue;const d=Math.hypot(x-w.x,y-w.y),fall=Math.max(0,1-(d/w.r)**2);wx+=w.ax*fall;wy+=w.ay*fall;}return {gx,gy,wx,wy,planets};}
