function valid(b){if(!Array.isArray(b)||b.length<2||b.length>63)return '조종석 1개와 엔진 1개 이상을 배치하세요.';const occupied=new Set();for(const m of b){if(!m||!Number.isInteger(m.x)||!Number.isInteger(m.y)||m.x<0||m.x>8||m.y<0||m.y>6||!['body','cockpit','engine'].includes(m.type))return '올바르지 않은 부품입니다.';const w=m.w??1,h=m.h??1;if(!Number.isInteger(w)||!Number.isInteger(h)||!([1,2].includes(w)&&[1,2].includes(h))||m.x+w>9||m.y+h>7||(m.type!=='body'&&(w!==1||h!==1)))return '부품 규격 또는 배치 범위를 확인하세요.';for(let yy=m.y;yy<m.y+h;yy++)for(let xx=m.x;xx<m.x+w;xx++){const key=xx+','+yy;if(occupied.has(key))return '부품이 겹쳤습니다.';occupied.add(key);}if(m.type==='engine'&&(!Number.isFinite(m.start)||!Number.isFinite(m.end)||m.start<0||m.end>30||m.end<=m.start||!['up','down','left','right'].includes(m.dir)))return '엔진 시간은 0~30초, 종료는 시작보다 커야 합니다.';}if(b.filter(m=>m.type==='cockpit').length!==1)return '조종석은 정확히 1개 필요합니다.';if(!b.some(m=>m.type==='engine'))return '엔진을 1개 이상 붙여 주세요.';let reached=new Set([b[0]]),queue=[b[0]];while(queue.length){const m=queue.pop();for(const n of b)if(!reached.has(n)&&(((n.x===m.x+(m.w??1)||m.x===n.x+(n.w??1))&&n.y<m.y+(m.h??1)&&m.y<n.y+(n.h??1))||((n.y===m.y+(m.h??1)||m.y===n.y+(n.h??1))&&n.x<m.x+(m.w??1)&&m.x<n.x+(n.w??1)))){reached.add(n);queue.push(n);}}return reached.size===b.length?'':'모든 부품을 상하좌우로 연결하세요.';}
function create(b,world=makeWorld()){const err=valid(b);if(err)throw new Error(err);b=syncGroups(JSON.parse(JSON.stringify(b)));let props=properties(b),cockpit=b.find(m=>m.type==='cockpit');return {b,world:JSON.parse(JSON.stringify(world)),...props,x:120+props.cx-cockpit.x*CELL,y:430+props.cy-cockpit.y*CELL,vx:0,vy:0,angle:0,omega:0,t:0,state:'flying',reason:'',active:0,thrust:0};}
function step(s,dt=DT,goalRadius=GOAL.r){if(s.state!=='flying')return s;let fx=0,fy=0,torque=0;s.active=0;s.thrust=0;const cos=Math.cos(s.angle),sin=Math.sin(s.angle);for(const g of groups(s.b))if(s.t+1e-8>=g.start&&s.t+1e-8<g.end){let [dx,dy]=directions[g.dir],force=FORCE*g.n;fx+=(dx*cos-dy*sin)*force;fy+=(dx*sin+dy*cos)*force;torque+=((g.x-s.cx)*dy-(g.y-s.cy)*dx)*force;s.active++;s.thrust+=force;}const field=environment(s.world,s.x,s.y,s.t);s.field=field;const ax=fx/s.mass+field.gx+field.wx,ay=fy/s.mass+field.gy+field.wy,alpha=torque/s.inertia;s.x+=s.vx*dt+ax*dt*dt/2;s.y+=s.vy*dt+ay*dt*dt/2;s.angle+=s.omega*dt+alpha*dt*dt/2;s.vx+=ax*dt;s.vy+=ay*dt;s.omega+=alpha*dt;s.t+=dt;const polygons=s.world.planets.map(p=>planetPolygon(p,s.t));for(const m of s.b){const rect=corners(s,m);if(polygons.some(p=>overlap(rect,p))){s.state='failure';s.reason='우주선이 행성에 충돌했습니다.';break;}if(rect.some(p=>p.x<0||p.x>1000||p.y<0||p.y>600)){s.state='failure';s.reason='우주선이 비행 영역을 벗어났습니다.';break;}}let cockpit=s.b.find(m=>m.type==='cockpit'),cp=transform(s,cockpit.x*CELL,cockpit.y*CELL);if(s.state==='flying'&&Math.hypot(cp.x-GOAL.x,cp.y-GOAL.y)<=goalRadius){s.state='success';s.reason='조종석이 목표 지점에 도착했습니다.';}if(s.state==='flying'&&s.t>=30-1e-8){s.t=30;s.state='failure';s.reason='30초 안에 목표에 도착하지 못했습니다.';}return s;}
